504	    <script type="application/ld+json">
505	    {
506	        "@context": "https://schema.org",
507	        "@type": "WebSite",
508	        "name": "Modern Web Template",
509	        "description": "A modern, accessible website built with best practices",
510	        "url": "https://example.com/",
511	        "author": {
512	            "@type": "Organization",
513	            "name": "Web Developer"
514	        },
515	        "mainEntity": {
516	            "@type": "CreativeWork",
517	            "name": "Modern Web Template",
518	            "description": "A semantic HTML5 template with accessibility and responsive design"
519	        }
520	    }
521	    </script>
