523	    <script>
524	        document.addEventListener('DOMContentLoaded', function() {
525	            const menuToggle = document.querySelector('.menu-toggle');
526	            const navMenu = document.getElementById('nav-menu');
527	
528	            if (menuToggle) {
529	                menuToggle.addEventListener('click', function() {
530	                    const isExpanded = menuToggle.getAttribute('aria-expanded') === 'true';
531	                    menuToggle.setAttribute('aria-expanded', !isExpanded);
532	                    navMenu.toggleAttribute('hidden');
533	                });
534	
535	                const navLinks = navMenu.querySelectorAll('a');
536	                navLinks.forEach(link => {
537	                    link.addEventListener('click', function() {
538	                        menuToggle.setAttribute('aria-expanded', 'false');
539	                        navMenu.setAttribute('hidden', '');
540	                    });
541	                });
542	            }
543	
544	            const learnMoreBtn = document.getElementById('learn-more-btn');
545	            if (learnMoreBtn) {
546	                learnMoreBtn.addEventListener('click', function() {
547	                    const getStartedSection = document.getElementById('get-started');
548	                    if (getStartedSection) {
549	                        getStartedSection.scrollIntoView({ behavior: 'smooth', block: 'start' });
550	                        getStartedSection.querySelector('#name').focus();
551	                    }
552	                });
553	            }
554	
555	            const contactForm = document.getElementById('contact-form');
556	            if (contactForm) {
557	                contactForm.addEventListener('submit', function(e) {
558	                    e.preventDefault();
559	                    const submitBtn = document.getElementById('submit-btn');
560	                    const feedback = document.getElementById('form-feedback');
561	
562	                    submitBtn.disabled = true;
563	                    const originalText = submitBtn.textContent;
564	                    submitBtn.textContent = 'Sending...';
565	
566	                    setTimeout(() => {
567	                        submitBtn.disabled = false;
568	                        submitBtn.textContent = originalText;
569	                        feedback.className = 'form-feedback success';
570	                        feedback.textContent = 'Thank you for your message! We\'ll be in touch soon.';
571	                        contactForm.reset();
572	                        feedback.focus();
573	                    }, 1000);
574	                });
575	            }
576	        });
577	    </script>
